raw_commands:
{#- Petty-cash expense slip, 80mm thermal. 42 columns, double width only (never double height). -#}
{%- set W = qz_columns(42) -%}
{%- set INIT = "\x1b@\x1c\x2e\x1b\x74\x00" -%}
{%- set BOLD_ON = "\x1b\x45\x01" -%}
{%- set BOLD_OFF = "\x1b\x45\x00" -%}
{%- set LEFT = "\x1b\x61\x00" -%}
{%- set CENTER = "\x1b\x61\x01" -%}
{%- set DBLW = "\x1d\x21\x10" -%}
{%- set NORMAL = "\x1d\x21\x00" -%}
{%- set HR = "-" * W -%}
{%- set CUT = "\x1b\x64\x04\x1d\x56\x00" -%}
{%- macro pair(label, value) -%}
{{ label }}{{ (value|string).rjust(W - label|length) }}
{%- endmacro -%}
{%- set issuer = (frappe.get_fullname(doc.owner) or doc.owner).split(" ")[0] -%}
{%- set amount = frappe.utils.fmt_money(doc.total_debit, currency=frappe.db.get_value("Company", doc.company, "default_currency")) -%}
{%- set when = frappe.utils.format_datetime(doc.creation, "dd-MMM-yyyy HH:mm") -%}
{{ INIT }}{{ CENTER }}{{ BOLD_ON }}{{ doc.company }}{{ BOLD_OFF }}
{{ doc.custom_warehouse or "" }}
{{ DBLW }}PETTY CASH EXPENSE{{ NORMAL }}
{{ LEFT }}{{ HR }}
{{ pair("Date:", when) }}
{{ pair("Ref:", doc.name) }}
{{ pair("Type:", doc.custom_expense_type or "") }}
{%- set note = (doc.user_remark or "").split(": ", 1)[1] if ": " in (doc.user_remark or "") else "" %}
{%- if note %}
{{ pair("Note:", note) }}
{%- endif %}
{{ BOLD_ON }}{{ pair("Amount:", amount) }}{{ BOLD_OFF }}
{%- if doc.docstatus == 0 %}
Status: Awaiting approval
{%- endif %}
{{ HR }}
Issued by: {{ issuer }}


Received by: {{ "_" * (W - 13) }}
{{ CUT }}
